/* Canonicalize ASCII references received from storage bin terminals. */
bool normalize_storage_bin_ref(const char *src, char *dst, size_t cap) {
    if (!src || !dst) return false;
    size_t first = 0, last = strlen(src);
    while (first < last && src[first] == ' ') ++first;
    while (last > first && src[last - 1] == ' ') --last;
    size_t size = last - first;
    if (!size || cap <= size) return false;
    /* memmove allows source and destination to overlap. */
    memmove(dst, src + first, size);
    for (size_t i = 0; i < size; ++i) {
        unsigned char ch = (unsigned char)dst[i];
        if (ch >= 'a' && ch <= 'z') dst[i] = (char)(ch - 'a' + 'A');
    }
    dst[size] = '\0';
    return true;
}

